const el=(tag,text='',cls='')=>{const node=document.createElement(tag);node.textContent=text;node.className=cls;return node;};
import {declareControl} from '/shared/workspace-presentation.mjs';
const label=displayLabel;
const relationNames={prerequisite:'Requires',support:'Draws on',counterevidence:'Counterevidence',questions:'Questions',validated_by:'Validated by',implementation:'Implemented by',analogy:'Analogy'};
const ns='http://www.w3.org/2000/svg';
const svgEl=(tag,attrs={})=>{const node=document.createElementNS(ns,tag);for(const [key,value]of Object.entries(attrs))node.setAttribute(key,value);return node;};

export function conceptCoverings(data={},plan={}){const known=new Map([...(plan.objects||[]),...(plan.containers||[])].map(row=>[row.id,row]));return (data.children||[]).filter(row=>(row.has_children||row.child_count>0)&&!['section','references','citation'].includes(row.kind)).map(row=>({...known.get(row.id),...row}));}
export function namedConceptState(state={},plan={}){const known=new Map([...(plan.objects||[]),...(plan.containers||[])].map(row=>[row.id,row]));return {...state,neighbors:(state.neighbors||[]).map(row=>{const found=known.get(row.id);return {...row,...(found?.title?{title:found.title}:{})};})};}
export function placementPresentations(placements=[]){const rows=[],byExact=new Map();for(const record of placements){const key=JSON.stringify(record);let row=byExact.get(key);if(!row){row={record,records:[]};rows.push(row);byExact.set(key,row);}row.records.push(record);}return rows;}

