    const links=(label,ids,empty)=>{const section=el('section','','argument-context-links');section.append(el('h4',label));if(!ids.length)section.append(el('p',empty,'muted'));else for(const id of ids)section.append(button(names(id),()=>openContext(all.find(item=>item.id===id)||{id},false)));body.append(section);};
