      const more=button('More objects',async()=>{const rows=context.members.slice(offset,offset+12);offset+=rows.length;for(const item of rows){if(!live())return;const row=el('article','','argument-member');row.append(button(label(item),()=>openContext(item,false)),el('span',displayConceptKind(item),'concept-type'));const summary=el('div','','scientific-prose argument-member-meaning');row.append(summary);memberSection.insertBefore(row,more);const meaning=item.meaning||item.summary||item.essence||item.label||'';if(!item.title&&!item.projection?.title&&String(meaning).replace(/\s+/g,' ').trim()===label(item))summary.remove();else await scientificText(summary,meaning);}more.hidden=offset>=context.members.length;more.textContent='Show next '+Math.min(12,context.members.length-offset)+' objects';});memberSection.append(more);await more.onclick();if(!live())return;
      links('Requires outside this group',context.requires,'No prerequisites outside this group are declared.');links('Used outside this group by',context.usedBy,'No uses outside this group are declared.');
