  const resize=new ResizeObserver(()=>{const next={width:viewport.clientWidth,height:viewport.clientHeight};if(!next.width||!next.height)return;camera=resizedArgumentCamera(camera,viewportSize,next,world,cameraFitted);viewportSize=next;paintCamera();if(popup?.context){const width=placeContext(popup.context.node),mini=popup.querySelector('[data-local-argument-svg]');if(mini){const box=mini.viewBox.baseVal;mini.setAttribute('height',String(box.height*(width-30)/box.width));}}});resize.observe(viewport);await load(true);
